#!/usr/bin/env bash
# ============================================================================
# Patch: تطبيق الهوية البصرية الجديدة لـ SwiftPay (خلفية سوداء)
# ============================================================================
# يطبّق:
#   - أيقونة التطبيق (adaptive + legacy + round) مستخرجة من رمز الـS الجديد،
#     على خلفية سوداء قريبة من النقية (#0D0F11) بدل التصميم القديم (البرق الأزرق/البنفسجي).
#   - شاشة splash الأصلية (native) باللوغو الكامل (S + SwiftPay) على نفس الخلفية السوداء.
#   - أيقونات PWA/الويب (favicon, apple-touch-icon, icon-192/512, maskable) بنفس الأسلوب.
#   - تحديث capacitor.config.json (ألوان splash + androidScaleType=CENTER_INSIDE لمنع قصّ الكلمة).
#
# لا يلمس: أي كود Java/Kotlin، AndroidManifest.xml، gradle، أو منطق app.js.
#
# Idempotent: التشغيل مرتين ينتج نفس النتيجة تمامًا (يطبع 'محدث مسبقًا' بالمرة الثانية).
# نسخ احتياطية تلقائية للملفات المستبدلة داخل docs/patches/backup_branding_<timestamp>/
# ============================================================================
set -euo pipefail
ROOT="${1:-$(pwd)}"
TS="$(date +%s)"
BACKUP_DIR="$ROOT/docs/patches/backup_branding_$TS"
CHANGED=0

[ -d "$ROOT/branding" ] && [ -d "$ROOT/www" ] || { echo "خطأ: شغله من جذر مشروع SwiftPay (لازم يحوي branding/ و www/)."; exit 1; }

write_file() {
  local rel="$1"
  local b64="$2"
  local dst="$ROOT/$rel"
  local tmp
  tmp="$(mktemp)"
  echo "$b64" | base64 -d > "$tmp"
  if [ -f "$dst" ] && cmp -s "$tmp" "$dst"; then
    rm -f "$tmp"
    return
  fi
  mkdir -p "$(dirname "$dst")"
  if [ -f "$dst" ]; then
    mkdir -p "$BACKUP_DIR/$(dirname "$rel")"
    cp "$dst" "$BACKUP_DIR/$rel.bak"
  fi
  mv "$tmp" "$dst"
  echo "    تم تحديث: $rel"
  CHANGED=$((CHANGED + 1))
}

echo "==> تطبيق أيقونة SwiftPay الجديدة (خلفية سوداء) + splash + أيقونات الويب..."

F1=""
write_file "branding/mipmap-source/mipmap-hdpi/ic_launcher_round.png" "$F1"
write_file "android/app/src/main/res/mipmap-hdpi/ic_launcher_round.png" "$F1"

